BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats7-q01', 'ベイズ統計',
   '40人のクラスで、犬を飼っているのは18人。その18人のうち、猫も飼っているのは6人だった。「犬を飼っている」と分かったうえで、その人が猫も飼っている確率はどれ？',
   NULL::text,
   '["6/18（=1/3）", "6/40（=3/20）", "18/40（=9/20）", "6/22（=3/11）"]',
   0, '[0]', 'single',
   '{"asked": "『〜と分かったうえで』という条件つきの確率の数え方。", "point": "条件が分かったら、まず母集団をその条件の人たちだけに絞る。割合はその絞った人数を分母にして数える。", "kid": "『犬を飼っている人の中で』と言われたら、クラス全体40人のことはいったん忘れて、犬を飼っている18人だけの世界に入り込む。その18人の中で猫も飼っている人が何人いるかを数えるのが条件付き確率。", "eg": "『めがねをかけている人の中で、視力0.1未満の人はどれくらい？』と聞かれたら、めがねをかけていない人はそもそも数えに入れない。最初から対象を絞ったグループの中だけで割合を出す。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">40人のうち「犬を飼っている18人」に世界を絞る</text><rect x=\"30\" y=\"30\" width=\"280\" height=\"80\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"30\" y=\"30\" width=\"126\" height=\"27\" fill=\"#3b82f6\"/><rect x=\"30\" y=\"57\" width=\"126\" height=\"53\" fill=\"#2a2f3f\"/><rect x=\"156\" y=\"30\" width=\"154\" height=\"80\" fill=\"#2a2f3f\" opacity=\"0.35\"/><line x1=\"156\" y1=\"24\" x2=\"156\" y2=\"116\" stroke=\"#60a5fa\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/><text x=\"93\" y=\"24\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">犬を飼っている18人</text><text x=\"93\" y=\"47\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">猫も飼っている 6人</text><text x=\"93\" y=\"87\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">猫は飼っていない 12人</text><text x=\"233\" y=\"47\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">犬を飼っていない22人</text><text x=\"233\" y=\"60\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">（今回は対象外）</text><text x=\"170\" y=\"128\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">求めたいのは 6/18（=1/3）</text><text x=\"170\" y=\"142\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">分母は40人ではなく、絞った18人</text></svg>", "terms": [["条件付き確率", "ある条件が分かったうえでの確率。母集団をその条件の範囲に絞ってから数える"], ["母集団", "割合を考えるときの、全体の集まり"]], "think": "なぜ分母が40ではなく18になるのかがカギ。もし分母を40のままにすると『犬を飼っていない22人』まで一緒に数えてしまい、『犬を飼っている人の中では』という条件の意味が消えてしまう。『〜の中で』と言われた時点で考える世界はその18人だけに狭まっているので、割合の分母もその18人にしないと、条件つきの問いに答えたことにならない。だから6人を18人で割る。", "vs": "『クラス全体で猫も犬も飼っている割合』(6/40)と、『犬を飼っている人の中で猫も飼っている割合』(6/18)は似ているようでまったく違う問い。条件つきかどうかで、分母にする人数が変わる。", "why_asked": "この後に出てくるベイズの定理は、条件付き確率を逆向きに計算し直す道具。まず条件付き確率そのものの数え方(絞ってから数える)が体に入っていないと、逆向きの計算の意味が分からなくなる。", "usecase": "『このアプリを使っている人の中で、有料会員になった割合』のような分析はすべて条件付き確率。全ユーザーではなく、条件に合う人だけを分母にして計算する。", "opt": ["正解。『犬を飼っている』で世界を18人に絞り、その中で猫も飼っている6人の割合を出す。6÷18=1/3。", "6÷40はクラス全員を分母にした割合(=3/20)。『犬を飼っている人の中で』という条件が反映されていない。", "18÷40は『クラス全体のうち犬を飼っている割合』(=9/20)。今回聞かれている『その中での猫の割合』とは別の問い。", "6÷22は犬を飼っていない22人を分母にした割合(=3/11)。条件は『犬を飼っている』なので、22人は対象外。"]}'),

  ('stats7-q03', 'ベイズ統計',
   '同じ福引き。店主に聞くと『並んでいる箱はA箱が80%、B箱が20%の割合』とのこと。まだ誰も箱を引いておらず、当たりが出たかどうかも分かっていない今の時点で言える『この箱はA箱だろう』という80%という確率を何と呼ぶ？',
   NULL::text,
   '["事前確率", "事後確率", "尤度", "条件付き確率"]',
   0, '[0]', 'single',
   '{"asked": "証拠を見る前の時点の確率の名前。", "point": "まだ結果(当たりかどうか)を見ていない段階での見込みが事前確率。", "kid": "事前確率は、『これから起きる結果を何も見ていない、今の時点での見込み』。福引きなら、箱を引く前に店主から聞いた『A箱が80%の割合で置いてある』が事前確率にあたる。", "eg": "天気予報でいうと、まだ空を見上げてもいない朝5時の時点で『今日は晴れの予報80%』と聞いているようなもの。まだ何も自分の目で確かめていない見込みが事前確率。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">まだ1回も箱を引いていない、今の時点の割合</text><rect x=\"30\" y=\"46\" width=\"224\" height=\"34\" fill=\"#3b82f6\"/><rect x=\"254\" y=\"46\" width=\"56\" height=\"34\" fill=\"#c9a04a\"/><text x=\"142\" y=\"67\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">A箱 80%</text><text x=\"282\" y=\"67\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"700\">B箱</text><text x=\"282\" y=\"78\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">20%</text><text x=\"170\" y=\"104\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">当たりが出たかどうかは、まだ関係ない</text><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">証拠を見る前の見込み ＝ 事前確率</text></svg>", "terms": [["事前確率", "証拠(結果)を見る前の時点での見込みの確率"], ["事後確率", "証拠を見たあとに更新された見込みの確率"]], "think": "なぜ『事前』とわざわざ呼ぶのかがカギ。この後、実際に箱を引いて当たりが出るという新しい情報(証拠)が入ってくる。その証拠を見る前と後で、見込みの数字は変わる可能性がある。だから『いつの時点の確率か』を区別するために、証拠より前の見込みには事前確率、証拠より後の見込みには事後確率、という別の名前を付けている。", "vs": "条件付き確率は『何かが分かったうえで』の確率全般を指す広い言葉。事前確率は、その中でも特に『まだ結果を見る前』という条件の確率を指す、狭い使い方。", "why_asked": "ベイズの定理は『事前確率を、証拠を使って事後確率に更新する』計算そのもの。出発点である事前確率が何を指すのかを取り違えると、更新の計算全体が狂う。", "usecase": "占い・診断・審査など、まず持っている情報だけでの見込みからスタートして、新しい情報が来るたびに見込みを更新していく場面すべてで、出発点として使う。", "opt": ["正解。まだ当たりが出たかどうかを見ていない段階の見込みなので、事前確率と呼ぶ。", "事後確率は当たりが出たという証拠を見たあとに更新された見込み。今回はまだ証拠を見る前の話。", "尤度は『A箱だったときに当たりが出る確率』のように、原因を仮定したときの結果の出やすさ。80%はそれとは別物。", "条件付き確率は『〜と分かったうえで』の確率全般の呼び方。事前確率はその中でも証拠より前の見込みを指す、より狭い言葉。"]}'),

  ('stats7-q04', 'ベイズ統計',
   '同じ福引き。A箱を引くと当たりが出る確率は25%、B箱を引くと当たりが出る確率は5%だと分かっている。この『その箱を選んだ場合に、当たりが出る確率』のことを何と呼ぶ？',
   NULL::text,
   '["尤度", "事前確率", "事後確率", "条件付き確率"]',
   0, '[0]', 'single',
   '{"asked": "『その原因なら、この結果がどれくらい出やすいか』を表す確率の名前。", "point": "尤度は『原因(箱の種類)を先に決めたときに、その結果(当たり)がどれくらい出やすいか』を表す。", "kid": "尤度は、『もしA箱だったなら』という仮定のもとで、当たりがどれくらい出やすいかを表す確率。箱の種類ごとに、当たりの出やすさの違いを教えてくれる数字。", "eg": "『雨の日にかさを持っている人が多い』というときの『雨の日なら、かさを持っている確率は90%』にあたる。原因(雨)を先に決めて、そこから結果(かさを持つ)の出やすさを見ている。", "viz": "<svg viewBox=\"0 0 340 142\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">その箱を選んだ場合に、当たりが出る確率</text><text x=\"85\" y=\"38\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">A箱を引いたとき</text><rect x=\"20\" y=\"52\" width=\"32.5\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"52.5\" y=\"52\" width=\"97.5\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"85\" y=\"86\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">当たり 25%</text><text x=\"255\" y=\"38\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">B箱を引いたとき</text><rect x=\"190\" y=\"52\" width=\"6.5\" height=\"20\" fill=\"#3b82f6\"/><rect x=\"196.5\" y=\"52\" width=\"123.5\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"255\" y=\"86\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">当たり 5%</text><text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">同じ「当たり」でも、箱によって出やすさが違う</text><text x=\"170\" y=\"130\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">この出やすさの違いが尤度</text></svg>", "terms": [["尤度", "原因を仮定したときに、その結果がどれくらい出やすいかを表す確率"], ["感度", "病気の検査などで、原因(病気)があるときに正しく検出できる確率。尤度の一種"]], "think": "尤度と事後確率は、数字の形は似ていても向きがまったく逆というのがカギ。尤度は『原因(箱)が分かっているとして、結果(当たり)がどれくらい出るか』を聞いている。事後確率は反対に『結果(当たり)が分かっているとして、原因(箱)がどれくらいそれっぽいか』を聞いている。同じ2つの出来事(箱と当たり)を扱っていても、どちらを先に決めて、どちらを知りたいのかが入れ替わっている。", "vs": "条件付き確率という大きな枠組みの中で、『原因が分かっているときの結果の確率』を特に尤度と呼び、『結果が分かっているときの原因の確率』を事後確率と呼ぶ。向きが逆であることを覚える。", "why_asked": "現実には『結果は見えるが、原因は見えない』ことが多い(当たりは見えるが、A箱かB箱かは分からない、症状は見えるが病気そのものは見えない)。そこで、見える結果と原因の結びつきの強さを表す尤度が、事後確率を計算するための材料として必要になる。", "usecase": "医療検査の感度(病気の人が陽性になる確率)、迷惑メール判定(迷惑メールなら『無料』という言葉が入っている確率)は、どれも尤度の実例。", "opt": ["正解。A箱だったときに当たりが出る確率25%、B箱だったときに当たりが出る確率5%は、原因を仮定したときの結果の出やすさ、つまり尤度。", "事前確率は当たりが出るかどうかとは関係なく、箱の割合そのものの見込み(80%・20%)。今回の25%・5%とは別物。", "事後確率は当たりが出たと分かったあとの、箱についての確率。今回の25%・5%は逆向きに、箱が分かっているときの当たりの確率。", "条件付き確率という呼び方自体は正しい枠組みだが、原因が先に分かっているときの結果の確率を特に指す言葉としては尤度が使われる。"]}'),

  ('stats7-q02', 'ベイズ統計',
   '屋台の福引き。箱にはAとBの2種類があり、店主が用意する割合はA箱80%、B箱20%（事前確率）。A箱を引くと当たりが出る確率は25%、B箱を引くと当たりが出る確率は5%（尤度）。ここまで分かっているとき、「当たりが出た」と分かったうえで実際にはA箱だった確率（事後確率）を求めるには、次のどの考え方を使う？',
   NULL::text,
   '["A箱の事前確率と尤度を掛けて、A経由とB経由の当たりを合わせた全体で割る", "当たりが出る尤度(A箱25%・B箱5%)の数字を、そのまま事後確率の値として使う", "A箱の事前確率(80%)の数字を、そのまま事後確率の値として使う", "A箱の事前確率と尤度の2つの数字を、そのまま足し合わせて事後確率とする"]',
   0, '[0]', 'single',
   '{"asked": "事前確率と尤度から事後確率を計算し直す、ベイズの定理の考え方。", "point": "事後確率＝（その原因での事前確率×尤度）÷（すべての原因を合わせた同じ結果の起こりやすさ）。", "kid": "ベイズの定理は、『結果を見る前の見込み(事前確率)』と『その原因ならその結果がどれくらい出やすいか(尤度)』を掛け合わせ、それを全部の原因について合計したもので割ることで、『結果を見たあとの見込み(事後確率)』を計算し直す公式。", "eg": "刑事が容疑者を絞り込むときと同じ。最初の疑わしさ(事前確率)に、現場の証拠がその人ならどれくらい出やすいか(尤度)を掛け合わせて、証拠を見たあとの疑わしさ(事後確率)に更新する。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">福引きの箱当て：事前確率 × 尤度 → 人数で比べる</text><text x=\"45\" y=\"40\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">経路</text><text x=\"140\" y=\"40\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">事前確率</text><text x=\"225\" y=\"40\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">尤度</text><text x=\"295\" y=\"40\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">当たり人数</text><line x1=\"20\" y1=\"48\" x2=\"320\" y2=\"48\" stroke=\"#2a2f3f\"/><text x=\"45\" y=\"68\" fill=\"#60a5fa\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">A箱</text><text x=\"140\" y=\"68\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">80%</text><text x=\"225\" y=\"68\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">×25%</text><text x=\"295\" y=\"68\" fill=\"#3b82f6\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">20人</text><text x=\"45\" y=\"92\" fill=\"#60a5fa\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">B箱</text><text x=\"140\" y=\"92\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">20%</text><text x=\"225\" y=\"92\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">×5%</text><text x=\"295\" y=\"92\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">1人</text><line x1=\"20\" y1=\"104\" x2=\"320\" y2=\"104\" stroke=\"#2a2f3f\"/><text x=\"45\" y=\"122\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">合計</text><text x=\"295\" y=\"122\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">21人</text><text x=\"170\" y=\"142\" fill=\"#60a5fa\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">事後確率 = 20 ÷ 21（A経由の割合）</text></svg>", "terms": [["ベイズの定理", "事前確率と尤度から事後確率を計算し直す公式"], ["尤度", "ある原因を仮定したときに、その結果がどれくらい出やすいかを表す確率"]], "think": "なぜ『掛けて、全体で割る』のかがカギ。A箱の事前確率80%に尤度25%を掛けると、100人のうちA箱経由で当たる人数(20人)が出る。同じようにB箱では1人。当たった人は合わせて21人しかいないので、そのうちA箱経由の20人が占める割合こそが『当たりが出たと分かったうえでの、A箱だった確率』になる。事前確率だけでも尤度だけでも、この『当たった人の中での割合』にはならない。両方を掛けて、全体で割ってはじめて答えになる。", "vs": "尤度をそのまま答えにする間違いが一番多い。尤度は『原因が分かっているときに結果がどれくらい出やすいか』の確率で、向きが逆。知りたいのは『結果が分かったときに原因がどれくらいそれっぽいか』であり、これが事後確率。", "why_asked": "『結果から原因をさかのぼりたい』という場面は、迷惑メール判定、病気の検査、故障診断など無数にある。尤度と事前確率という手元にある情報だけから、求めたい事後確率を正しく計算する手順を持っていないと、勘に頼るしかなくなる。", "usecase": "迷惑メールフィルタ、医療診断、故障の原因診断、天気予報の更新など、新しい証拠が来るたびに見込みを計算し直すシステムの土台。", "opt": ["正解。A箱の事前確率×尤度でA経由の当たり人数(20人)を出し、B経由(1人)と合わせた全体(21人)で割ると、当たったあとのA箱の確率20/21が求まる。", "尤度25%・5%は『A箱(またはB箱)だったときに当たりが出る確率』であって、『当たりが出たときにA箱だった確率』とは向きが逆。そのままでは答えにならない。", "80%は当たりを見る前の見込み(事前確率)。当たりを引いたという新しい証拠を反映していないので、更新した答えにはならない。", "事前確率と尤度は掛け合わせるべきもので、足し算では『当たった人数のうちの割合』という求めたい答えにならない。"]}'),

  ('stats7-q05', 'ベイズ統計',
   '同じ福引きで100人が1回ずつ箱を引いたとする。A箱の人80人のうち当たったのは20人、B箱の人20人のうち当たったのは1人だった。当たった21人の中で、実際にA箱だった人の割合はどれ？',
   NULL::text,
   '["20/21", "1/21", "20/100", "80/100"]',
   0, '[0]', 'single',
   '{"asked": "証拠(当たり)を見たあとに計算し直した、原因(箱)についての確率。", "point": "当たった人だけに世界を絞り、その中でA箱だった人数を数える。20÷21が事後確率。", "kid": "事後確率は、『当たりが出た』という証拠を実際に見たあとで、『じゃあA箱だった確率はどれくらいか』を計算し直した確率。当たった21人だけの世界に絞って、その中でA箱だった人の割合を数える。", "eg": "警察が『犯人はこの中の誰か』を、最初の疑わしさ(事前確率)から、指紋という新しい証拠(尤度)を踏まえて『この証拠が出たならこの人が犯人である確率はこれくらい』と更新するのと同じ。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">100人が1回ずつ引いたとして数える（自然頻度）</text><text x=\"24\" y=\"46\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">A箱80人</text><rect x=\"30\" y=\"52\" width=\"56\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"86\" y=\"52\" width=\"168\" height=\"24\" fill=\"#2a2f3f\"/><text x=\"58\" y=\"68\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">当たり20人</text><text x=\"170\" y=\"68\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">はずれ60人</text><text x=\"24\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"start\">B箱20人</text><rect x=\"30\" y=\"98\" width=\"3\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"33\" y=\"98\" width=\"53\" height=\"24\" fill=\"#2a2f3f\"/><text x=\"60\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">当たり1人・はずれ19人</text><text x=\"170\" y=\"144\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">当たった21人のうち、A箱由来は20人 → 20/21</text></svg>", "terms": [["事後確率", "証拠を見たあとに更新された、原因についての確率"], ["自然頻度", "割合や%ではなく、実際の人数で考える数え方。ベイズの計算をイメージしやすくする"]], "think": "なぜ分母が100人ではなく21人になるのかがカギ。知りたいのは『当たりが出たと分かったうえで』の話なので、条件付き確率のときと同じく、まず当たった21人だけの世界に絞る必要がある。100人全員を分母にしてしまうと、まだ当たりが出たかどうか分からない79人まで一緒に数えてしまい、『当たりが出たと分かったうえで』という条件の意味が消えてしまう。21人の中でA箱経由が20人だから、20÷21が事後確率になる。", "vs": "事前確率(80%)は当たりが出る前の箱の見込み。事後確率(20/21≈95%)は当たりが出たあとに更新された見込み。同じA箱についての確率でも、証拠を見る前と後で数字が変わっている。", "why_asked": "新しい証拠を得たら見込みをどう更新するかは、ベイズの定理そのものの目的地。事前確率・尤度を材料にして、最終的にたどり着きたい答えが事後確率。", "usecase": "検査で陽性が出た人が本当に病気である確率、迷惑メールフィルタが最終的に出す『このメールが迷惑メールである確率』は、どれも事後確率。", "opt": ["正解。当たった21人だけに絞り、その中でA箱経由の20人の割合を数える。20÷21が事後確率。", "1÷21はB箱経由の割合。今回聞かれているのはA箱だった確率。", "20÷100は当たっていない人も含めた100人全員を分母にした割合で、『当たったと分かったうえで』という条件が反映されていない。", "80÷100は当たりが出る前のA箱の事前確率そのもの。当たりが出たという証拠がまだ反映されていない。"]}'),

  ('stats7-q06', 'ベイズ統計',
   '迷惑メールフィルタは、最初『このメールが迷惑メールである確率は50%』と見積もっていた。件名に『無料』という言葉があることを確認し、確率を50%から80%に更新した。続けて本文に『今すぐクリック』という言葉も見つかった。次に確率を更新する正しいやり方はどれ？',
   NULL::text,
   '["80%を新しい事前確率として、もう一度尤度を掛けて更新する", "最初に見積もった50%まで戻して、そこからもう一度計算し直す", "80%のままにしておき、新しく見つかった言葉は特に反映しない", "80%の数字と新しい証拠による尤度を、そのまま足し算する"]',
   0, '[0]', 'single',
   '{"asked": "証拠が増えるたびに確率を計算し直す、ベイズ更新の考え方。", "point": "1回目の事後確率が、そのまま2回目の事前確率になる。証拠が増えるたびにこれを繰り返す。", "kid": "ベイズ更新は、証拠が1つ増えるたびに、前の答え(事後確率)を次の出発点(事前確率)にして、もう一度事後確率を計算し直すこと。証拠が増えるほど、見込みはどんどん正確に近づいていく。", "eg": "刑事が容疑者を絞り込むとき、最初の証拠(現場に残った指紋)で疑わしさを更新し、次の証拠(目撃情報)が出たら、さっき更新した疑わしさを出発点にして、さらに更新する。ゼロからやり直したりはしない。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">証拠が増えるたびに、確率を計算し直す</text><rect x=\"30\" y=\"26\" width=\"280\" height=\"20\" fill=\"#2a2f3f\"/><rect x=\"30\" y=\"26\" width=\"140\" height=\"20\" fill=\"#60a5fa\"/><text x=\"170\" y=\"41\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">最初の見込み 50%</text><text x=\"170\" y=\"60\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">件名に「無料」を発見</text><rect x=\"30\" y=\"68\" width=\"280\" height=\"20\" fill=\"#2a2f3f\"/><rect x=\"30\" y=\"68\" width=\"224\" height=\"20\" fill=\"#3b82f6\"/><text x=\"170\" y=\"83\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">更新後 80%</text><text x=\"170\" y=\"102\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">本文に「今すぐクリック」も発見</text><rect x=\"30\" y=\"110\" width=\"280\" height=\"20\" fill=\"#2a2f3f\"/><rect x=\"30\" y=\"110\" width=\"266\" height=\"20\" fill=\"#3b82f6\"/><text x=\"170\" y=\"125\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"700\">さらに更新 95%</text><text x=\"170\" y=\"143\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">前回の事後確率が、次の事前確率になる</text></svg>", "terms": [["ベイズ更新", "新しい証拠が入るたびに、前回の事後確率を次の事前確率として使い、確率を計算し直すこと"], ["事後確率", "証拠を見たあとに更新された確率"]], "think": "なぜ前回の事後確率をそのまま次の事前確率にしてよいのかがカギ。『件名に無料がある』という証拠を織り込んだ80%は、その時点で分かっている情報をすべて反映した、いちばん新しい見込み。次に『今すぐクリック』という証拠が来たとき、また最初の50%からやり直したら、せっかく『無料』という証拠から得た情報を捨ててしまうことになる。だから前回たどり着いた80%を新しい出発点にして、そこにもう一段、新しい証拠の尤度を掛けて更新するのが正しい。", "vs": "『80%のまま変えない』は新しい証拠(今すぐクリック)を無視する誤り。『50%からやり直す』は前回の証拠(無料)まで無視する誤り。ベイズ更新は、これまでの証拠を全部積み上げながら少しずつ確率を動かしていく。", "why_asked": "迷惑メール判定にかぎらず、証拠は1回で全部そろうことはめったにない。証拠が来るたびにゼロからやり直していては、それまでの情報がすべて無駄になる。積み上げながら更新する仕組みが無いと、情報が増えるほど計算が破綻する。", "usecase": "迷惑メールフィルタ、レコメンド機能(クリックのたびに好みの見込みを更新)、医療の経過観察(検査を重ねるたびに診断の確率を更新)など、証拠が少しずつ増える場面で使う考え方。", "opt": ["正解。前回の事後確率80%を新しい事前確率として使い、そこに『今すぐクリック』の尤度を掛けてもう一度更新する。", "50%からやり直すと、『無料』という言葉から得た情報を捨ててしまうことになる。せっかく更新した見込みが無駄になる。", "80%のまま変えないのは、『今すぐクリック』という新しい証拠を無視すること。証拠が増えたのに見込みを更新しないのは誤り。", "確率どうしは掛け合わせて更新するものであり、足し算では『当たった場合の割合』のような正しい答えにならない。"]}'),

  ('stats7-q07', 'ベイズ統計',
   'ある珍しい病気は、10000人に10人がかかっている。この病気の検査は、病気の人にはほぼ確実に陽性と出て、健康な人にも1%の確率で誤って陽性(偽陽性)と出てしまう。ある人がこの検査を受けて陽性だった。この人が本当に病気である確率に一番近いのはどれ？',
   NULL::text,
   '["約9%", "約99%", "約50%", "ほぼ0%"]',
   0, '[0]', 'single',
   '{"asked": "検査の精度が高くても、珍しい病気では陽性が本物とは限らない理由。", "point": "陽性者の中身は『本物の病気』と『健康な人の誤検出』が混ざっている。珍しい病気ほど、後者の人数が本物を上回りやすい。", "kid": "この検査、当てるだけならかなり優秀に見える。でも『陽性です』と言われた人の中には、本当に病気の人だけでなく、健康なのに間違って陽性になった人もたくさん混ざっている。病気の人がもともとすごく少ないと、間違って陽性になった健康な人の数のほうが、本物の病気の人の数より多くなってしまうことがある。", "eg": "1万人が入る競技場を思い浮かべる。本当に病気なのはたった10人。残り9990人は健康なのに、そのうち1%の約100人が誤って陽性と判定される。陽性の呼び出しを受けた人は10人+100人=110人。そのうち本物は10人だけなので、呼ばれても本物である確率はそう高くない。", "viz": "<svg viewBox=\"0 0 340 154\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">10000人の内訳</text><rect x=\"140\" y=\"20\" width=\"60\" height=\"18\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"32\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">10000人</text><line x1=\"150\" y1=\"38\" x2=\"95\" y2=\"58\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><polygon points=\"95,58 99.4,53.9 101.0,58.3\" fill=\"#2a2f3f\"/><line x1=\"190\" y1=\"38\" x2=\"250\" y2=\"58\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><polygon points=\"250,58 244.0,58.5 245.5,54.0\" fill=\"#2a2f3f\"/><text x=\"90\" y=\"70\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">病気 10人</text><text x=\"252\" y=\"70\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">健康 9990人</text><line x1=\"90\" y1=\"76\" x2=\"60\" y2=\"96\" stroke=\"#c47070\" stroke-width=\"1.5\"/><polygon points=\"60,96 63.3,91.0 65.9,94.9\" fill=\"#c47070\"/><line x1=\"252\" y1=\"76\" x2=\"225\" y2=\"96\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><polygon points=\"225,96 228.0,90.8 230.8,94.6\" fill=\"#c9a04a\"/><line x1=\"252\" y1=\"76\" x2=\"300\" y2=\"96\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><polygon points=\"300,96 294.0,96.0 295.8,91.7\" fill=\"#8892a4\"/><rect x=\"30\" y=\"98\" width=\"60\" height=\"20\" fill=\"#c47070\" opacity=\"0.85\"/><text x=\"60\" y=\"112\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">陽性 10人</text><rect x=\"195\" y=\"98\" width=\"60\" height=\"20\" fill=\"#c9a04a\" opacity=\"0.85\"/><text x=\"225\" y=\"112\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">陽性 100人</text><text x=\"300\" y=\"108\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">陰性</text><text x=\"300\" y=\"118\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">9890人</text><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">陽性は合計110人（本物10人＋誤検出100人）</text><text x=\"170\" y=\"149\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"700\">本当に病気なのは 10/110 ≈ 9%</text></svg>", "terms": [["有病率", "その病気に実際にかかっている人の割合。ここでは10000人に10人"], ["偽陽性", "本当は病気ではないのに、検査で誤って陽性と出てしまうこと"], ["基礎率", "もともとその出来事がどれくらいの割合で起きるかという、大元の割合。ここでは有病率がそれにあたる"]], "think": "なぜ検査の精度が高いのに、当たる確率がそこまで高くならないのかがカギ。10000人を病気の10人と健康な9990人に分ける。病気の10人はほぼ全員陽性になるので10人。健康な9990人のうち1%が誤って陽性になるので、9990×0.01=約100人。つまり陽性と出た人は合わせて約110人いて、その中身は『本物10人』と『誤検出100人』。健康な人の数がもともと圧倒的に多いので、1%というわずかな誤り率でも、誤検出の人数(100人)が本物(10人)を大きく上回ってしまう。だから陽性が出ても本当に病気である確率は10÷110で約9%にとどまる。", "vs": "検査の性能(病気の人をほぼ確実に当てる、健康な人を1%しか間違えない)がどれだけ高くても、そもそも病気にかかっている人がどれくらい少ないか(基礎率)を無視すると、答えを大きく見誤る。『検査が優秀だから陽性は病気に違いない』という思い込みが、この罠の正体。", "why_asked": "健康診断や新型の検査が話題になるたびに、検査の精度だけが強調され、そもそもその病気がどれくらい珍しいかが見落とされがち。この見落とし(基礎率の無視)は、統計を知らないと専門家でもうっかりやってしまう、代表的な落とし穴として必ず取り上げられる。", "usecase": "がん検診やウイルス検査の結果を正しく受け止めるとき、不正利用検知(まれな不正を大量の正常な取引の中から見つける)、スパム判定など、珍しい出来事を大量のデータから探すシステム全般で、この考え方を踏まえないと誤解を招く。", "opt": ["正解。陽性110人のうち本物の病気は10人だけなので、10÷110で約9%。検査の精度の高さだけでは決まらない。", "約99%は検査の『病気の人をほぼ確実に当てる性能』の数字であり、『陽性と出た人が本当に病気である確率』とは別物。", "約50%は陽性か陰性かを五分五分と考えた場合の値で、実際の人数の内訳(本物10人・誤検出100人)を反映していない。", "ほぼ0%は病気の珍しさだけを見て、検査で陽性が出たという新しい証拠を無視した考え方。"]}'),

  ('stats7-q08', 'ベイズ統計',
   '天気予報が『明日の降水確率は70%』と言った。この70%という数字を、『今ある雲の様子などの情報から見て、明日雨が降るとどれくらい確信できるか』という確信の度合いとして捉える考え方はどれ？',
   NULL::text,
   '["ベイズ主義。確率を『今ある証拠から見て、その出来事をどれくらい確信できるか』という度合いとして捉える。1回きりの出来事にも確率を割り当てられる。", "頻度主義。確率を『同じ状況を何度も繰り返したときに、その出来事が起きる長期的な割合』として捉える。1回きりの出来事には確率を割り当てにくいとされる。", "頻度主義。確率を『今ある証拠から見て、その出来事をどれくらい確信できるか』という度合いとして捉える立場のことを指す言葉。", "ベイズ主義。確率を『同じ状況を何度も繰り返したときに、その出来事が起きる長期的な割合』として捉える立場のこと。"]',
   0, '[0]', 'single',
   '{"asked": "確率という数字を、2つの流派がそれぞれどう解釈しているか。", "point": "『同じ状況を繰り返した長期の割合』と考えるのが頻度主義、『今の証拠からの確信の度合い』と考えるのがベイズ主義。", "kid": "同じ『確率70%』という数字でも、2つの考え方がある。頻度主義は『同じことを100回繰り返したら70回くらい起きるはず』という長期的な繰り返しの割合として考える。ベイズ主義は『今持っている情報から見て、70%くらいそうなると思う』という確信の強さとして考える。", "eg": "サイコロを100回振って1の目が出た回数を数えるのは頻度主義的な発想。一方、明日という1回きりの日の天気に70%という数字を付けられるのは、繰り返しではなく確信の度合いとして確率を扱っているから。ベイズ主義的な発想。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">頻度主義</text><rect x=\"20\" y=\"50\" width=\"140\" height=\"18\" fill=\"#2a2f3f\"/><rect x=\"20\" y=\"50\" width=\"98\" height=\"18\" fill=\"#60a5fa\"/><text x=\"90\" y=\"78\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">100回繰り返した中の</text><text x=\"90\" y=\"90\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">70回、という長期の割合</text><line x1=\"180\" y1=\"10\" x2=\"180\" y2=\"130\" stroke=\"#2a2f3f\"/><text x=\"250\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">ベイズ主義</text><rect x=\"210\" y=\"30\" width=\"40\" height=\"80\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\" rx=\"4\"/><rect x=\"210\" y=\"54\" width=\"40\" height=\"56\" fill=\"#3b82f6\" rx=\"4\"/><text x=\"230\" y=\"68\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\">70%</text><text x=\"250\" y=\"78\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">今の証拠から見た</text><text x=\"250\" y=\"90\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">「確信の度合い」</text><text x=\"170\" y=\"144\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ「70%」でも、意味づけが違う</text></svg>", "terms": [["頻度主義", "確率を、同じ状況を何度も繰り返したときの長期的な割合として捉える立場"], ["ベイズ主義", "確率を、今ある証拠からの確信の度合いとして捉える立場"]], "think": "なぜ『明日の天気』のような1回きりの出来事に確率を付けられるかがカギ。頻度主義は『何度も繰り返して、そのうち何回起きるか』を数えることで確率を定義する。しかし明日という日は繰り返せない、たった1回の出来事なので、頻度主義の定義のままでは『明日の降水確率70%』の意味を説明しづらい。ベイズ主義は確率を『繰り返し』ではなく『今の証拠に基づく確信の強さ』として定義し直すので、1回きりの出来事にも確率を割り当てられる。ここまで学んできた事前確率・尤度・事後確率という考え方は、このベイズ主義の立場に立っている。", "vs": "どちらが正しい・間違っているというより、確率という同じ数字の意味づけが違う2つの立場。頻度主義は『長期的な繰り返しの割合』、ベイズ主義は『確信の度合い』。名前と説明の組み合わせを取り違えやすいので注意する。", "why_asked": "ここまでの事前確率・事後確率という考え方は、確率を確信の度合いとして更新できるものとみなすベイズ主義があってはじめて成り立つ。この立場の違いを知らないと、なぜベイズ統計という別の流派がわざわざ存在するのかが分からなくなる。", "usecase": "天気予報の降水確率、選挙の当落予想、スポーツの勝敗予想など、1回きりの出来事に確率〇%と付けられている場面は、たいていベイズ主義的な確信の度合いとして解釈されている。", "opt": ["正解。ベイズ主義は確率を確信の度合いとして捉えるので、明日という1回きりの出来事にも70%という確率を付けられる。", "これは頻度主義の正しい説明。ただし頻度主義は繰り返しの割合として確率を考えるので、1回きりの明日の天気には本来なじみにくい立場。", "『確信の度合い』という説明はベイズ主義のものであり、頻度主義の説明としては名前と中身が入れ替わっている。", "『長期的な割合』という説明は頻度主義のものであり、ベイズ主義の説明としては名前と中身が入れ替わっている。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
